INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Proyek Arduino Butuh Input Tombol$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Banyak proyek membutuhkan masukan dari pengguna: kode PIN pintu, pilihan menu, atau memasukkan angka. Memakai 16 tombol tekan terpisah akan menghabiskan 16 pin digital Arduino. Keypad matriks 4x4 memberi 16 tombol hanya dengan 8 pin — jauh lebih hemat dan rapi.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Cara Kerja Keypad Matriks$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Ke-16 tombol disusun dalam matriks 4 baris dan 4 kolom. Arduino melakukan pemindaian (scanning): mengaktifkan satu baris dalam satu waktu, lalu membaca kolom mana yang terhubung saat tombol ditekan. Library Keypad menangani seluruh proses scanning dan debounce (anti-pantulan tombol) secara otomatis.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Alat dan Bahan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$$Arduino Uno atau Nano$$, $$Keypad membran 4x4$$, $$Kabel jumper secukupnya$$, $$Kabel USB dan komputer dengan Arduino IDE$$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah 1: Merangkai Kabel (Wiring)$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Hubungkan 8 pin keypad ke 8 pin digital Arduino, misalnya pin 2 sampai 9. Empat pin pertama untuk baris (R1-R4) dan empat berikutnya untuk kolom (C1-C4). Urutan kabel tidak kritis selama sesuai dengan definisi pin di program. Pastikan konektor keypad membran terpasang rapat karena mudah longgar.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Langkah 2: Memasang Library dan Mengunggah Program$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Di Arduino IDE buka Sketch, lalu Include Library, lalu Manage Libraries. Cari Keypad buatan Mark Stanley dan klik Install. Buat sketch baru: definisikan peta tombol 4x4 berisi karakter 0-9, A-D, bintang, dan pagar; buat objek Keypad dengan pin baris dan kolom yang dipakai; di dalam loop() baca keypad.getKey() dan cetak hasilnya ke Serial Monitor pada 9600 baud. Unggah program lalu buka Serial Monitor.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Risiko dan Kesalahan Umum$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$$Urutan pin baris/kolom di program tidak cocok dengan kabel: tombol terbaca salah. Sesuaikan definisi rowPins dan colPins dengan kabel fisik.$$, $$Library Keypad belum terpasang: muncul error kompilasi Keypad.h: No such file. Pasang dulu lewat Library Manager.$$, $$Konektor keypad membran longgar: sebagian tombol tidak merespons. Tekan konektor hingga rapat.$$, $$Kabel jumper putus di dalam: sulit dilacak secara visual. Uji dengan multimeter bila dicurigai.$$, $$Pemeriksaan hasil: tekan semua 16 tombol satu per satu dan pastikan karakter yang muncul di Serial Monitor sesuai label tombol.$$, $$Tindak lanjut: gabungkan dengan LCD 16x2 untuk menampilkan input, atau buat sistem kunci kombinasi dan kalkulator sederhana.$$, $$Peringatan: keypad hanya untuk sinyal logika 5V. Jangan hubungkan ke tegangan 220V atau beban besar.$$])));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Ayam Pop Keras dan Hambar$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Ayam pop yang benar berwarna pucat keemasan, dagingnya empuk, dan gurih sampai ke dalam, disajikan dengan sambal merah khas Padang. Kegagalan umum: ayam keras karena digoreng terlalu lama, dan rasa hambar karena bumbu tidak sempat meresap.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Kunci Ayam Pop Autentik$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Rahasianya ada pada dua tahap. Pertama, ungkep: ayam direbus perlahan dalam air kelapa dan bumbu hingga empuk dan meresap. Kedua, goreng sangat sebentar dalam minyak benar-benar panas hanya untuk memberi warna keemasan tipis. Air kelapa memberi rasa gurih manis alami yang tidak bisa digantikan air biasa.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Bahan (4 Porsi)$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$$1 ekor ayam kampung sekitar 1 kg, potong 4 bagian$$, $$500 ml air kelapa$$, $$300 ml santan encer$$, $$5 siung bawang putih$$, $$4 butir kemiri sangrai$$, $$1 ruas jahe$$, $$1 ruas lengkuas, geprek$$, $$2 batang serai, geprek$$, $$3 lembar daun salam$$, $$1 sendok makan garam$$, $$1 sendok teh gula pasir$$, $$Minyak goreng secukupnya$$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah 1-3: Ungkep Ayam$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Haluskan bawang putih, kemiri, dan jahe. Masukkan ayam, bumbu halus, lengkuas, serai, daun salam, garam, dan gula ke dalam panci. Tuang air kelapa dan santan hingga ayam terendam. Rebus dengan api kecil selama 30 sampai 40 menit hingga ayam empuk dan kuah menyusut. Angkat dan tiriskan.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Langkah 4-5: Goreng Sekilas dan Sajikan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Panaskan minyak yang banyak hingga benar-benar panas. Goreng ayam 1 sampai 2 menit saja per sisi hingga keemasan pucat, jangan sampai kecokelatan. Angkat dan tiriskan minyaknya. Sajikan dengan nasi hangat, sambal merah khas Padang, dan lalapan segar.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Risiko dan Kesalahan Umum$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$$Digoreng terlalu lama: ayam pop berubah menjadi ayam goreng biasa yang keras dan cokelat. Batasi maksimal 2 menit per sisi.$$, $$Api ungkep terlalu besar: santan pecah dan bumbu tidak meresap. Selalu gunakan api kecil.$$, $$Ayam broiler diungkep terlalu lama: daging hancur. Untuk ayam broiler cukup 20 sampai 25 menit.$$, $$Pemeriksaan hasil: daging empuk mudah disobek dengan garpu, warna pucat keemasan, rasa gurih meresap sampai ke tulang.$$, $$Penyimpanan: ayam hasil ungkep yang belum digoreng tahan 2 hari di kulkas atau 1 minggu di freezer.$$])));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Gas yang Tersembunyi$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Nama kripton berasal dari bahasa Yunani kryptos yang berarti tersembunyi. Gas ini ditemukan pada tahun 1898 oleh William Ramsay dan Morris Travers saat meneliti sisa udara cair. Sesuai namanya, kripton bersembunyi di atmosfer dalam jumlah sangat kecil: hanya sekitar 1 bagian per juta udara.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Sifat-sifat Kripton$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Kripton termasuk gas mulia: tidak berwarna, tidak berbau, dan sangat sulit bereaksi dengan unsur lain. Ia lebih berat daripada udara dan mencair pada suhu minus 153 derajat Celsius. Seperti gas mulia lainnya, kulit elektron terluarnya sudah penuh sehingga ia sangat malas membentuk ikatan kimia.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Dari Mana Kripton Berasal$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Kripton diperoleh dari penyulingan udara cair di pabrik pemisahan udara skala industri. Karena kadarnya amat kecil, memproduksi kripton murni membutuhkan energi besar sehingga harganya jauh lebih mahal dibanding argon atau nitrogen.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Kegunaan dalam Kehidupan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Kripton dipakai pada lampu pijar dan lampu kilat fotografi berdaya tinggi karena cahayanya terang dan efisien. Campuran kripton dan fluor menghasilkan laser excimer yang dipakai untuk operasi mata LASIK dan pembuatan chip semikonduktor. Ia juga dipakai sebagai gas pengisi jendela kaca ganda agar insulasi panasnya lebih baik.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Fakta Menarik$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Meski namanya dipakai untuk kryptonite, batu kelemahan Superman, kripton asli sama sekali tidak berbahaya dan tidak radioaktif. Isotop kripton-85 memang bersifat radioaktif, tetapi ia hanya terbentuk dari aktivitas nuklir buatan manusia, bukan dari kripton yang ada di alam.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Apa Itu Dwikora$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Dwikora adalah singkatan dari Dwi Komando Rakyat, seruan Presiden Soekarno pada 3 Mei 1964. Seruan ini menjadi dasar politik konfrontasi Indonesia terhadap pembentukan Federasi Malaysia yang dinilai sebagai kelanjutan pengaruh kolonial Inggris di kawasan.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Latar Belakang: Lahirnya Malaysia$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Pada tahun 1963 Inggris menggabungkan Malaya, Singapura, Sabah, dan Sarawak menjadi Federasi Malaysia. Indonesia menolak pembentukan ini dengan alasan penggabungan Sabah dan Sarawak yang berbatasan langsung dengan Kalimantan tidak menghormati aspirasi rakyat setempat dan memperluas pengaruh Inggris di Asia Tenggara.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Isi Dwi Komando Rakyat$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Dwikora berisi dua perintah. Pertama, memperkuat ketahanan revolusi Indonesia. Kedua, membantu perjuangan rakyat Malaya, Singapura, Sabah, dan Sarawak untuk membebaskan diri dari kekuasaan Inggris. Seruan ini memobilisasi dukungan rakyat luas serta pengerahan kekuatan militer, terutama di perbatasan Kalimantan.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Jalannya Konfrontasi$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Konfrontasi berlangsung dari tahun 1963 hingga 1966 dalam bentuk infiltrasi, pertempuran terbatas di perbatasan Kalimantan, dan operasi di Semenanjung Malaya. Pengerahan pasukan terbesar terjadi di Kalimantan, disertai sejumlah insiden yang melibatkan sukarelawan Indonesia di wilayah Malaysia.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Akhir Konfrontasi$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Setelah pergantian kepemimpinan nasional kepada Soeharto, Indonesia dan Malaysia menandatangani Perjanjian Bangkok pada 11 Agustus 1966. Perjanjian ini mengakhiri konfrontasi dan memulihkan hubungan diplomatik kedua negara, membuka babak baru kerja sama regional di Asia Tenggara.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Setelah mempelajari materi ini, siswa diharapkan mampu menjelaskan pengertian interaksi sosial, menyebutkan syarat terjadinya interaksi sosial, mengidentifikasi bentuk-bentuk interaksi sosial, serta menganalisis faktor yang memengaruhi interaksi sosial dalam kehidupan sehari-hari.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Pengertian Interaksi Sosial$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Interaksi sosial adalah hubungan timbal balik antara individu dengan individu, individu dengan kelompok, atau kelompok dengan kelompok yang saling memengaruhi. Tanpa interaksi sosial tidak ada kehidupan bermasyarakat: manusia mempelajari norma, bahasa, dan budaya melalui interaksi dengan sesamanya.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Syarat Terjadinya Interaksi Sosial$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$$Kontak sosial: hubungan yang terjadi secara fisik langsung maupun melalui media, misalnya bertatap muka, menelepon, atau berkirim pesan.$$, $$Komunikasi: penyampaian pesan beserta pemahaman maknanya, misalnya melalui bahasa lisan, bahasa isyarat, atau tulisan.$$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Bentuk-bentuk Interaksi Sosial$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Interaksi asosiatif bersifat membangun dan memperkuat persatuan, meliputi kerja sama, akomodasi, asimilasi, dan akulturasi. Interaksi disosiatif bersifat mengarah pada perpecahan, meliputi persaingan, kontravensi, dan konflik. Kedua bentuk ini selalu hadir dalam masyarakat dan perlu dikelola agar tidak merusak tatanan sosial.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Contoh dalam Kehidupan Sehari-hari$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Gotong royong membersihkan lingkungan adalah contoh kerja sama yang asosiatif. Debat calon ketua OSIS yang sehat adalah kontravensi, yaitu perbedaan pendapat tanpa kekerasan. Tawuran antarpelajar adalah konflik yang disosiatif dan harus dicegah melalui mediasi serta penegakan aturan sekolah.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Latihan Soal$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$$1. Jelaskan dua syarat terjadinya interaksi sosial beserta contohnya masing-masing!$$, $$2. Sebutkan tiga bentuk interaksi asosiatif dan berikan contohnya!$$, $$3. Mengapa konflik digolongkan sebagai interaksi disosiatif? Jelaskan!$$, $$Kunci jawaban: 1. Kontak sosial, contohnya bertemu tetangga; komunikasi, contohnya berdiskusi kelompok. 2. Kerja sama contoh gotong royong, akomodasi contoh mediasi, asimilasi contoh pernikahan campur. 3. Karena konflik mengarah pada perpecahan dan merusak persatuan, bukan membangunnya.$$])));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Setelah belajar materi ini, kamu dapat menjelaskan apa itu kenampakan buatan, menyebutkan contoh kenampakan buatan di sekitarmu, dan menjelaskan manfaatnya bagi kehidupan manusia.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Apa Itu Kenampakan Buatan?$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Kenampakan buatan adalah segala sesuatu di permukaan bumi yang dibuat oleh manusia, bukan terbentuk sendiri oleh alam. Lawannya adalah kenampakan alam seperti gunung, sungai, dan laut yang terbentuk secara alami tanpa campur tangan manusia.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Contoh Kenampakan Buatan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$$Waduk dan bendungan untuk menampung air$$, $$Sawah dan perkebunan untuk bercocok tanam$$, $$Jalan raya, jembatan, dan pelabuhan untuk transportasi$$, $$Gedung sekolah, rumah sakit, dan pasar$$, $$Bandara sebagai tempat pesawat terbang lepas landas$$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Kenampakan Buatan di Sekitar Kita$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Perhatikan perjalananmu ke sekolah setiap hari. Jalan yang kamu lewati, jembatan yang kamu seberangi, dan gedung sekolah tempatmu belajar adalah kenampakan buatan. Bahkan sawah tempat petani menanam padi termasuk kenampakan buatan karena dibentuk oleh manusia.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Manfaat Kenampakan Buatan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Kenampakan buatan memudahkan hidup manusia. Waduk menyimpan air untuk musim kemarau, jalan menghubungkan desa dengan kota, dan sekolah memberi tempat belajar yang nyaman. Namun pembuatannya harus memperhatikan kelestarian alam agar tidak merusak lingkungan.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Ayo Berlatih!$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$$1. Apa perbedaan kenampakan alam dan kenampakan buatan?$$, $$2. Sebutkan 3 contoh kenampakan buatan di desa atau kotamu!$$, $$3. Apa manfaat waduk bagi manusia?$$, $$Kunci jawaban: 1. Kenampakan alam terbentuk sendiri oleh alam, kenampakan buatan dibuat oleh manusia. 2. Jawaban beragam, contohnya jalan, jembatan, sekolah, sawah, atau masjid. 3. Menampung air untuk irigasi sawah, air minum, dan pembangkit listrik.$$])));
